def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]

    sep_rows = [r for r, row in enumerate(grid)
                if row[0] != bg and all(x == row[0] for x in row)]
    sep_cols = [c for c in range(w)
                if grid[0][c] != bg and all(grid[r][c] == grid[0][c] for r in range(h))]

    def segments(n, separators):
        result, start = [], 0
        for p in separators:
            if start < p:
                result.append((start, p))
            start = p + 1
        if start < n:
            result.append((start, n))
        return result

    rs, cs = segments(h, sep_rows), segments(w, sep_cols)
    tiles = []
    for r0, r1 in rs:
        for c0, c1 in cs:
            cells = [(r-r0, c-c0, grid[r][c])
                     for r in range(r0, r1) for c in range(c0, c1)
                     if grid[r][c] != bg]
            tiles.append((len(cells), cells))

    pattern = max(tiles, key=lambda t: t[0])[1]
    out = [[bg] * w for _ in range(h)]
    for r in sep_rows:
        out[r] = grid[r][:]
    for c in sep_cols:
        for r in range(h):
            out[r][c] = grid[r][c]

    for r0, r1 in rs:
        for c0, c1 in cs:
            for dr, dc, color in pattern:
                if r0 + dr < r1 and c0 + dc < c1:
                    out[r0 + dr][c0 + dc] = color
    return out
